function updateSheetHint(){const hint=$('#sheetHint');if(!hint)return;const listText=$('#count')?.textContent?.trim()||'목록 확인',mapText=$('#kakaoMapStatus')?.textContent?.trim()||'지도 확인 중',mapMode=state.page==='map'&&!state.expanded&&!state.selected;hint.innerHTML=mapMode?'<strong>'+esc(mapText)+'</strong><span>'+esc(listText)+'</span>':'<strong>'+esc(listText)+'</strong><span>'+esc(mapText)+'</span>';}
